pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // General rule: owner() should return the deployer (address(this) passed to constructor in setUp)
    // We fuzz an arbitrary address param just to satisfy fuzzer requirement; owner() takes no params,
    // but the test must accept at least one fuzzed parameter — we use a fuzzed address but do not pass it to owner().
    function testFuzz_property(address /*unusedFuzzed*/) public {
        // admissible domain: any address is fine
        // The reference contract returns the deployer address (address(this) in setUp())
        // The mutant returns address(0), so for many fuzz inputs this will differ.

        // Call owner() and assert it equals the deployer we used when constructing c
        address expectedOwner = address(this);
        address actualOwner = c.owner();
        assertTrue(actualOwner == expectedOwner);
    }
}

