    function testFuzz_property(address newOwner) public {
        // keep domain wide; no tight assumptions. We need the caller to be the owner, setUp deployer is owner.
        // ensure caller is the owner (address(this) is owner because setUp used address(this))
        // perform the call as the owner
        bool ok;
        // call transferOwnership as the owner (this contract)
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property for the reference: after transferOwnership returns (ok == true), owner() is never address(0).
