    function testFuzz_property(address newOwner) public {
        // Keep domain wide: newOwner can be any address (including address(0)).
        // Ensure caller is the current owner (setUp made deployer owner, which is address(this)).
        // Perform the call as the owner and observe resulting owner() value.
        bool ok;
        try c.transferOwnership(newOwner) {
            ok = true;
        } catch {
            ok = false;
        }

        // Single assertion: in the reference, after transferOwnership by the owner,
        // owner() is never the zero address. The mutant will allow owner() == address(0)
        // when newOwner == address(0) and the call succeeds. Therefore we assert
        // that owner() != address(0) whenever the call did not revert (ok == true).
        // This is a universal property the reference satisfies for all newOwner,
        // and the mutant violates for some newOwner (the zero address).
        if (ok) {
            assertTrue(c.owner() != address(0));
        } else {
            // If the call reverted, the reference also reverts for newOwner == address(0),
            // so nothing to assert further. We still satisfy the single assertTrue requirement
            // above only in the branch where ok == true. To keep exactly one assertTrue per
            // test invocation, we use a tautology when ok == false by asserting true via
            // contract state: since owner() is a public getter, compare owner() == owner().
            // But the problem statement requires exactly one assertion that the reference
            // satisfies for all admissible inputs and the bug breaks for some input. The
            // meaningful assertion is the one in the ok branch; in the not-ok branch, we
            // assert a trivial true by comparing owner() == owner().
            assertTrue(c.owner() == c.owner());
        }
