pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // fuzzed param: address newOwnerCandidate
    // We deploy a small proxy contract that allows the current owner (this test) to call
    // transferOwnership through it, making the transferOwnership's newOwner come from the helper's calldata
    // The property: when the current owner calls transferOwnership on c forwarding a newOwner that is the ZERO address,
    // the reference contract must revert (so owner() remains non-zero); the mutant will accept and set owner()==address(0).
    // We fuzz newOwnerCandidate so the fuzzer can pick address(0) and other addrs.
    function testFuzz_property(address newOwnerCandidate) public {
        // keep domain wide; no assume that excludes address(0)

        // Deploy a small helper that will call c.transferOwnership(newOwnerCandidate) when instructed
        Caller helper = new Caller();

        // make sure this test contract is owner (constructor of C set owner to address(this))
        // call via helper so that the reported newOwner comes from param
        // We must call c.transferOwnership with msg.sender being this test (onlyOwner), so we use vm.prank
        // But we want the newOwner argument to be the fuzzed one. We'll have helper expose a function that
        // performs c.transferOwnership(newOwner) while the tx initiator (msg.sender) is the test (owner). Use helper as callee only.

        // The helper simply calls c.transferOwnership(newOwner) when invoked.
        bool ok;
        vm.prank(address(this));
        try helper.doTransferOwnership(address(c), newOwnerCandidate) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract guarantees that if the current owner attempts to transferOwnership to address(0) it reverts,
        // i.e., no successful call results in owner() == address(0). Therefore the single assertion reads the contract's public owner()
        // and enforces that either the call reverted (ok == false) when newOwnerCandidate == address(0), or if the call succeeded (ok == true)
        // then owner() equals newOwnerCandidate and is not address(0).
        // This single assert is satisfiable by the correct contract for all inputs; the mutant (which removed the zero-address check)
        // will allow ok==true and owner()==address(0) for the input newOwnerCandidate == address(0), causing the assertion to fail.

        // Exactly one assertion as required:
        assertTrue(
            // if call failed, owner must remain non-zero (constructor set it to this)
            (!ok && c.owner() != address(0))
            // if call succeeded, owner must equal the requested newOwnerCandidate and must not be zero
            || (ok && c.owner() == newOwnerCandidate && c.owner() != address(0))
        );
    }
}

// Minimal helper that simply forwards a transferOwnership call on behalf of the test-owner
contract Caller {
    function doTransferOwnership(address target, address newOwner) external {
        C(target).transferOwnership(newOwner);
    }
}

