import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// The test deploys an adversarial helper that will be used as the "newOwner" and will perform an on-chain observation
// when it is queried (via a call) during the event emission flow. The reference implementation updates storage
// before any observer can see the new owner via owner(), so the helper should always observe owner()==newOwner
// during the event emission; the mutant that emits the event before updating storage can lead the helper to observe
// a different owner() during the emission. We fuzz the helper's behavior selector (a uint8) to ensure the fuzzer
// searches inputs; the deciding value is the helper address itself (deployed here) and a selector which the helper
// uses to decide whether to perform an extra read.

